class ConfirmationModal(LocalBasicPage):
    _MODAL_XPATH = '//div[@class="modal-content"]'

    def __init__(self, driver, download_checker=None):
        super(ConfirmationModal, self).__init__(driver, download_checker)

    def confirm(self):
        """
        Clicks confirm button in selenium_coam confirmation modal
        """
        pass

    def cancel(self):
        """
        Clicks cancel button in selenium_coam confirmation modal
        """
        pass

    def wait_until_modal_appear(self, locator, timeout=60):
        self.wait_for_visibility(locator, timeout)


class SessionEstablishmentError(ConfirmationModal):
    _SESSION_ESTAB_ERROR_MODAL = '//div[@class="modal-content"][//*[contains(@title, "Session establishment error")]]'
    _SESSION_ESTAB_ERROR_CONTENT = '//div[@class="modal-body"]'
    _MODAL_CLOSE_BUTTON = '//div[@class="modal-content"]//ui-button[@a-text="OK"]/button'

    def __init__(self, driver):
        super(SessionEstablishmentError, self).__init__(driver)

    def wait_until_session_estab_error_modal_appear(self, timeout=10):
        try:
            self.wait_until_modal_appear((By.XPATH, self._SESSION_ESTAB_ERROR_MODAL), timeout)
            return True
        except TimeoutException:
            logging.info("not found session establishment error modal")
            return False

    def get_session_estab_error(self):
        return self.get_text_by_xpath(self._SESSION_ESTAB_ERROR_CONTENT)

    def close(self):
        self.click_enabled_element((By.XPATH, self._MODAL_CLOSE_BUTTON))


