class ModalAfterLogin(ConfirmationModal):
    omit = False

    def __init__(self, driver):
        super(ModalAfterLogin, self).__init__(driver)

    def wait_until_login_modal_appear(self, timeout=60):
        try:
            self.wait_until_modal_appear((By.XPATH, self._MODAL_XPATH), timeout)
            if 'BTS Start-up View' in self.get_attribute_by_xpath(self._MODAL_XPATH + '//ui-modal', 'a-title'):
                self.omit = True
        except TimeoutException:
            logging.info(self._WARNING_MSG)

    def confirm(self, timeout=60):
        try:
            if not self.omit:
                self.click_enabled_element((By.XPATH, self._CLOSE_BUTTON_XPATH), timeout)
        except (TimeoutException, NoSuchElementException):
            logging.info("{}, interface function may be influenced".format(self._WARNING_MSG))


