class LoadScfFileModal(ConfirmationModal):
    _CLOSE_BUTTON_XPATH = '//div[@class="modal-content"]//ui-button[@a-text="Close"]/button'

    def __init__(self, driver):
        super(LoadScfFileModal, self).__init__(driver)
        self._load_scf_nodes = 4

    def wait_until_load_file_modal_appear(self, timeout=60):
        self.wait_until_modal_appear((By.XPATH, self._MODAL_XPATH), timeout)

    def confirm(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._CLOSE_BUTTON_XPATH), timeout)

    def check_status_after_loading_scf_file(self, check_node=4, timeout=60):
        """
        Check status after loading scf file
        """
        load_scf_file_node_status_xpath = '//div[@class="modal-body"]//ul//li[{}]'
        for index in range(1, self._load_scf_nodes + 1):
            node_status_xpath = load_scf_file_node_status_xpath.format(index)
            self.wait_for_text_present_in_attribute(node_status_xpath, "class", "ng-scope")
            node_status = self.get_attribute_by_xpath(node_status_xpath.format(index), "class", timeout)
            if "failed" in node_status:
                return False
        return True


