class CreateNewConfigurationModal(ConfirmationModal):

    def __init__(self, driver):
        super(CreateNewConfigurationModal, self).__init__(driver)

    def wait_for_creat_new_configuration_modal_appear(self, timeout):
        self.wait_until_modal_appear((By.XPATH, self._MODAL_XPATH), timeout)

    def _copy_configuration(self, is_copy, copy_configuration_from, timeout):
        _COPY_CONFIG_CHECKBOX_XPATH = self._MODAL_XPATH + '//span[contains(text(), "Copy configuration from")]'
        _COPY_CONFIG_DROPDOWN_BUTTON_XPATH = self._MODAL_XPATH + '//wf-dropdown//button'
        _COPY_CONFIG_OPTIONS_XPATH = self._MODAL_XPATH + '//wf-dropdown//li//span'

        if not is_copy:
            return
        if copy_configuration_from:
            self.click_enabled_element((By.XPATH, _COPY_CONFIG_CHECKBOX_XPATH), timeout)
            self.select_element_from_dropdown_list_by_text_and_click(
                copy_configuration_from,
                (By.XPATH, _COPY_CONFIG_DROPDOWN_BUTTON_XPATH),
                (By.XPATH, _COPY_CONFIG_OPTIONS_XPATH),
                timeout
            )
        else:
            raise AttributeError('param "copy_configuration_from" can not be None')

    def _configure_name(self, configuration_name, timeout):
        _CONFIGURATION_NAME_INPUT_XPATH = self._MODAL_XPATH + ('//li[contains'
                                                               '(@class, "new-configuration-name-complex")]//input')
        if configuration_name:
            self.insert_text_to_enable_element((By.XPATH, _CONFIGURATION_NAME_INPUT_XPATH),
                                               configuration_name,
                                               timeout)

    def create_new_configuration(self, is_copy, copy_configuration_from, configuration_name, timeout=60):
        _CREATE_BUTTON_XPATH = self._MODAL_XPATH + '//button[contains(text(), "Create")]'

        self._copy_configuration(is_copy, copy_configuration_from, timeout)
        self._configure_name(configuration_name, timeout)
        self.click_enabled_element((By.XPATH, _CREATE_BUTTON_XPATH), timeout)


class BtsStartUpViewModal(ConfirmationModal):
    _MODAL_XPATH = '//div[@class="modal-content"]//ui-modal[@*="BTS Start-up View"]'

