class LoadNcfFileModal(LoadScfFileModal):
    _NCF_ERROR_BASE_XPATH = '//xml-raml-validation//'
    _NCF_ERROR_TITLE_XPATH = '//validation-message//span'
    _NCF_ERROR_LABEL_XPATH = _NCF_ERROR_BASE_XPATH + 'label/b'
    _NCF_ERROR_HEAD_XPATH = _NCF_ERROR_BASE_XPATH + 'thead//th'
    _NCF_ERROR_COUNT_XPATH = _NCF_ERROR_BASE_XPATH + 'tbody/tr'
    _NCF_ERROR_ITEM_XPATH = _NCF_ERROR_BASE_XPATH + 'tbody/tr[{}]/td'
    _NCF_INFO_BASE_XPATH = '//ncf-skipped-elements-table//'
    _NCF_INFO_TITLE_XPATH = _NCF_INFO_BASE_XPATH + 'h2'
    _NCF_INFO_HEAD_XPATH = _NCF_INFO_BASE_XPATH + 'thead//th'
    _NCF_INFO_COUNT_XPATH = _NCF_INFO_BASE_XPATH + 'tbody/tr'
    _NCF_INFO_ITEM_XPATH = _NCF_INFO_BASE_XPATH + 'tbody/tr[{}]/td'

    def __init__(self, driver):
        super(LoadNcfFileModal, self).__init__(driver)
        self._load_scf_nodes = 3

    def _get_ncf_info(self, timeout, **kwargs):
        info_head_xpath = kwargs['head']
        info_count_xpath = kwargs['count']
        info_item_xpath = kwargs['item']

        info_list = []
        info_key_list = self.get_fields_info_from_row(info_head_xpath, timeout)
        info_count = len(self.driver.find_elements_by_xpath(info_count_xpath))
        for index in range(1, info_count + 1):
            info_value_xpath = info_item_xpath.format(index)
            info_value_list = self.get_fields_info_from_row(info_value_xpath, timeout)
            info_list.append(dict(zip(info_key_list, info_value_list)))
        return info_list

    def _get_ncf_info_logs(self, timeout):
        info_title = self.get_text_by_xpath_if_exist(self._NCF_INFO_TITLE_XPATH, timeout)
        if not info_title:
            return info_title

        info_xpath_dict = {'head': self._NCF_INFO_HEAD_XPATH,
                           'count': self._NCF_INFO_COUNT_XPATH,
                           'item': self._NCF_INFO_ITEM_XPATH}
        info_list = self._get_ncf_info(timeout, **info_xpath_dict)
        return {'title': info_title, 'info': info_list}

    def _get_ncf_error_logs(self, timeout):
        error_title = self.get_text_by_xpath_if_exist(self._NCF_ERROR_TITLE_XPATH, timeout)
        error_label = self.get_text_by_xpath_if_exist(self._NCF_ERROR_LABEL_XPATH, timeout)

        error_xpath_dict = {'head': self._NCF_ERROR_HEAD_XPATH,
                            'count': self._NCF_ERROR_COUNT_XPATH,
                            'item': self._NCF_ERROR_ITEM_XPATH}
        error_list = self._get_ncf_info(timeout, **error_xpath_dict)
        return {'title': error_title, 'label': error_label, 'info': error_list}

    def check_status_after_loading_ncf_file(self, timeout=60):
        """
        Check status after loading ncf file
        """
        load_ncf_status = self.check_status_after_loading_scf_file(timeout)
        return self._get_ncf_info_logs(timeout) if load_ncf_status else self._get_ncf_error_logs(timeout)


